The provider system (`src/engine/providers.ts`) defines the plugin architecture for content sources in kbexplorer. Each provider is a self-contained adapter that knows how to fetch content from one source — authored markdown, file trees, or work items — and produce `KBNode[]` arrays that the [orchestrator](orchestrator) assembles into a unified graph.

## The Provider Interface

Every provider implements the `GraphProvider` interface:

```typescript
interface GraphProvider {
  id: string;
  name: string;
  dependencies?: string[];
  resolve(config: KBConfig, existingNodes: KBNode[]): Promise<ProviderResult>;
}

interface ProviderResult {
  nodes: KBNode[];
  edges: KBEdge[];
}
```

The `dependencies` array declares which other providers must run first. The `existingNodes` parameter gives each provider access to previously collected nodes — enabling cross-provider edge creation.

## The Provider Registry

The `ProviderRegistry` class manages registration and execution ordering via depth-first topological sort:

- `register(provider)` — adds a provider
- `getExecutionOrder()` — returns providers in dependency-safe order
- `get(id)` — retrieves a provider by ID

This pattern was designed for extensibility. The [Graph Provider Architecture (#40)](https://github.com/anokye-labs/kbexplorer-template/issues/40) tracks the evolution, and [#42](https://github.com/anokye-labs/kbexplorer-template/issues/42) implemented the first provider interface alongside the graph store.

## Current Providers

| Provider | Source | What it produces |
|----------|--------|-----------------|
| [Authored Provider](authored-provider) | Markdown files + nodemap | Content nodes with frontmatter |
| [Files Provider](files-provider) | GitHub file tree | Directory and source file nodes |
| [Work Provider](work-provider) | GitHub issues/PRs/commits | Work item nodes |

## Future Providers

The planned GitHub/ADO provider ([#43](https://github.com/anokye-labs/kbexplorer-template/issues/43)) will add on-demand PR expansion with depth limits. The sense-making epic ([#54](https://github.com/anokye-labs/kbexplorer-template/issues/54)) laid groundwork for layer-based filtering that works with the provider model.

## Integration

The [local loader](local-loader) creates providers from the pre-built manifest and registers them. The [orchestrator](orchestrator) runs `getExecutionOrder()` and executes each sequentially. The [identity system](identity) ensures nodes from different providers with the same real-world referent get merged correctly. All provider types are defined in the [type system](type-system).

import { useEffect } from 'react';
import type { KBConfig } from '../types';
import { resolveImageUrl } from '../api';

/** Marker attribute on the single managed override <link>, so we can find/update/remove it idempotently. */
export const CSS_OVERRIDE_ATTR = 'data-kbe-css-override';

/**
 * Whether `value` is already an absolute URL that must be used verbatim rather
 * than resolved as a repo-relative path. Matches `http://`, `https://`, and
 * protocol-relative `//host/...` forms. resolveImageUrl() would otherwise
 * prefix BASE_URL / build a raw.githubusercontent URL and mangle these.
 */
export function isAbsoluteUrl(value: string): boolean {
  return /^https?:\/\//i.test(value) || value.startsWith('//');
}

/** Minimal element target that exposes the attribute API we need (testable without a DOM). */
export type CssLinkTarget = {
  getAttribute(name: string): string | null;
  setAttribute(name: string, value: string): void;
  remove(): void;
};

/** Minimal document target so this is testable without jsdom. */
export type CssDocTarget = {
  querySelector(selector: string): CssLinkTarget | null;
  createElement(tag: string): CssLinkTarget;
  head: { appendChild(el: CssLinkTarget): void };
};

/**
 * Inject (or update/remove) the host repo's raw CSS override sheet as a single
 * managed `<link rel="stylesheet">` appended LAST to <head> so its declarations
 * win the cascade over FluentProvider and the app's own styles.
 *
 * - When `href` is set: create the link if missing (tagged with
 *   {@link CSS_OVERRIDE_ATTR}) and point it at `href`. The href is only written
 *   when it changes, so re-renders don't trigger a needless re-fetch.
 * - When `href` is null/empty: remove any previously injected link so flipping
 *   the config back to unset cleanly tears the override down.
 * - The element is never duplicated: it is keyed by {@link CSS_OVERRIDE_ATTR}.
 */
export function applyCssOverride(href: string | null | undefined, doc?: CssDocTarget): void {
  const target = doc ?? (typeof document !== 'undefined' ? (document as unknown as CssDocTarget) : undefined);
  if (!target) return;

  const selector = `link[${CSS_OVERRIDE_ATTR}]`;
  let link = target.querySelector(selector);

  if (!href) {
    if (link) link.remove();
    return;
  }

  if (!link) {
    link = target.createElement('link');
    link.setAttribute('rel', 'stylesheet');
    link.setAttribute(CSS_OVERRIDE_ATTR, '');
    target.head.appendChild(link);
  }
  if (link.getAttribute('href') !== href) {
    link.setAttribute('href', href);
  }
}

/**
 * React hook that injects `config.branding.css` as the last stylesheet in
 * <head>. A repo-relative path is resolved via resolveImageUrl (the same
 * host-repo asset path the logo/favicon use); an absolute URL (http(s):// or
 * protocol-relative //) is used verbatim. Unset css injects nothing and removes
 * any previously injected sheet.
 */
export function useCssOverride(config: KBConfig | undefined): void {
  const css = config?.branding?.css;
  const href = css && config
    ? (isAbsoluteUrl(css) ? css : resolveImageUrl(config.source, css))
    : null;
  useEffect(() => {
    applyCssOverride(href);
  }, [href]);
}

import { useEffect } from 'react';
import type { KBConfig } from '../types';
import { resolveImageUrl } from '../api';

/** Minimal element target that exposes the attribute API we need (testable without a DOM). */
export type IconLinkTarget = {
  setAttribute(name: string, value: string): void;
};

/** Minimal document target so this is testable without jsdom. */
export type FaviconDocTarget = {
  querySelector(selector: string): IconLinkTarget | null;
  createElement(tag: string): IconLinkTarget;
  head: { appendChild(el: IconLinkTarget): void };
};

/**
 * Swap the document's `<link rel="icon">` href to the resolved favicon URL.
 *
 * When `href` is null/empty the function is a no-op so the static default in
 * index.html (`/favicon.svg`) is left untouched. When the link element is
 * missing it is created and appended to <head>.
 */
export function applyFavicon(href: string | null | undefined, doc?: FaviconDocTarget): void {
  if (!href) return;
  const target = doc ?? (typeof document !== 'undefined' ? (document as unknown as FaviconDocTarget) : undefined);
  if (!target) return;

  let link = target.querySelector('link[rel="icon"]');
  if (!link) {
    link = target.createElement('link');
    link.setAttribute('rel', 'icon');
    target.head.appendChild(link);
  }
  link.setAttribute('href', href);
}

/**
 * React hook that swaps the document favicon from `config.branding.favicon`
 * (resolved via resolveImageUrl, same host-repo asset path the logo uses) once
 * config is available. Unset favicon leaves the default /favicon.svg in place.
 */
export function useFavicon(config: KBConfig | undefined): void {
  const favicon = config?.branding?.favicon;
  const href = favicon && config ? resolveImageUrl(config.source, favicon) : null;
  useEffect(() => {
    applyFavicon(href);
  }, [href]);
}

import { useEffect } from 'react';
import type { KBGraph } from '../types';

/**
 * Global keyboard shortcuts.
 *
 * t          → cycle theme (built-ins + config themes, via the live theme map)
 * ←/→        → prev/next node (reading view)
 * Ctrl-K / / → open search palette (delegated to onOpenSearch)
 */
export function useKeyboardNav(
  graph: KBGraph | null,
  cycleTheme: () => void,
  onOpenSearch?: () => void,
): void {
  useEffect(() => {
    function handler(e: KeyboardEvent) {
      // Ctrl-K: open search palette (fires even inside inputs — mirrors VS Code
      // behaviour). When search is disabled (no onOpenSearch), let the browser
      // keep its default Ctrl-K behaviour instead of swallowing the key.
      if (onOpenSearch && (e.ctrlKey || e.metaKey) && e.key.toLowerCase() === 'k') {
        e.preventDefault();
        onOpenSearch();
        return;
      }

      const tag = (e.target as HTMLElement)?.tagName;
      if (tag === 'INPUT' || tag === 'TEXTAREA' || tag === 'SELECT') return;
      if ((e.target as HTMLElement)?.isContentEditable) return;

      switch (e.key) {
        case '/': {
          if (!onOpenSearch) break;
          e.preventDefault();
          onOpenSearch();
          break;
        }
        case 't': {
          cycleTheme();
          break;
        }
        case 'ArrowLeft':
        case 'ArrowRight': {
          if (!graph) break;
          const hash = window.location.hash;
          const match = hash.match(/#\/node\/(.+)/);
          if (!match) break;
          const currentId = decodeURIComponent(match[1]);
          const idx = graph.nodes.findIndex(n => n.id === currentId);
          if (idx < 0) break;
          const next = e.key === 'ArrowRight'
            ? (idx + 1) % graph.nodes.length
            : (idx - 1 + graph.nodes.length) % graph.nodes.length;
          window.location.hash = `#/node/${encodeURIComponent(graph.nodes[next].id)}`;
          break;
        }
      }
    }

    window.addEventListener('keydown', handler);
    return () => window.removeEventListener('keydown', handler);
  }, [graph, cycleTheme, onOpenSearch]);
}

import { useState, useEffect } from 'react';
import type { KBGraph, KBConfig, SourceConfig } from '../types';
import { detectLocalMode, loadLocalKnowledgeBase } from '../engine/local-loader';
import { loadRemoteKnowledgeBase } from '../engine/remote-loader';
import { isDemoEntitiesEnabled, injectDemoEntities, isBigOrgDemoEnabled, injectBigOrg } from '../engine/demo-entities';

export type LoadingState =
  | { status: 'loading' }
  | { status: 'ready'; graph: KBGraph; config: KBConfig }
  | { status: 'error'; error: string };

/**
 * Hook that loads the knowledge base.
 * In local mode: imports pre-built manifest (zero API calls).
 * In remote mode: fetches from GitHub API via the provider pipeline.
 */
export function useKnowledgeBase(sourceOverride?: SourceConfig): LoadingState {
  const [state, setState] = useState<LoadingState>({ status: 'loading' });

  useEffect(() => {
    let cancelled = false;

    async function load() {
      setState({ status: 'loading' });
      try {
        const local = await detectLocalMode();

        if (local) {
          const { graph, config } = await loadLocalKnowledgeBase();
          if (!cancelled) {
            if (graph.nodes.length === 0) {
              setState({
                status: 'error',
                error: 'No content found in local manifest. Run `npm run prebuild` to regenerate.',
              });
            } else {
              const finalGraph = applyDemoSeams(graph);
              exposeAuditGraph(finalGraph, config, 'local');
              setState({ status: 'ready', graph: finalGraph, config });
            }
          }
          return;
        }

        // Remote mode — fetch from GitHub API via the provider pipeline
        const { graph, config } = await loadRemoteKnowledgeBase(sourceOverride, 'standard');
        if (!cancelled) {
          if (graph.nodes.length === 0) {
            setState({
              status: 'error',
              error: 'No content loaded. The GitHub API may be rate-limited — try again in a minute, or check your network.',
            });
          } else {
            const finalGraph = applyDemoSeams(graph);
            exposeAuditGraph(finalGraph, config, 'remote');
            setState({ status: 'ready', graph: finalGraph, config });
          }
        }
      } catch (err) {
        if (!cancelled) {
          setState({
            status: 'error',
            error: err instanceof Error ? err.message : String(err),
          });
        }
      }
    }

    void load();
    return () => { cancelled = true; };
  }, [sourceOverride]);

  return state;
}

/**
 * Apply optional demo seams (off by default) to the loaded graph: small
 * entity demo (`?demo=entities`) and the large synthetic org tree
 * (`?demo=bigorg`, for exercising the reports-to layout at scale — #279).
 */
function applyDemoSeams(graph: KBGraph): KBGraph {
  let g = graph;
  if (isDemoEntitiesEnabled()) g = injectDemoEntities(g);
  if (isBigOrgDemoEnabled()) g = injectBigOrg(g);
  return g;
}

/**
 * Expose the resolved full graph + config on `window.__kbeGraph` so the
 * visual audit can probe the unfiltered topology. The HUD-mounted vis
 * networks only render a 40-node filtered view, so without this hook the
 * audit cannot tell whether disconnections happen in the data or only in
 * the visible subset. Storing references (not clones) — the audit is
 * read-only and the page is throwaway, so no mutation risk.
 */
function exposeAuditGraph(graph: KBGraph, config: KBConfig, mode: 'local' | 'remote'): void {
  if (typeof window === 'undefined') return;
  try {
    (window as unknown as { __kbeGraph?: unknown }).__kbeGraph = {
      mode,
      graph,
      config,
      stats: {
        nodes: graph.nodes.length,
        edges: graph.edges.length,
        clusters: graph.clusters.length,
      },
    };
  } catch {
    /* ignore — non-fatal */
  }
}

import { useState, useCallback } from 'react';
import type { KBConfig, FluentBrandRamp, FluentBrandRampKey } from '../types';
import {
  webDarkTheme,
  webLightTheme,
  createLightTheme,
  createDarkTheme,
  type Theme as FluentTheme,
  type BrandVariants,
} from '@fluentui/react-components';
import { generateBrandVariants } from '../theme/brandRamp';

/**
 * A selectable theme key. The three built-ins (dark/light/sepia) are always
 * present; config-defined themes (`config.theme.themes.<name>`) widen this set
 * at runtime, so the type is intentionally open. `(string & {})` keeps built-in
 * autocomplete while still accepting arbitrary config theme keys.
 */
export type ThemeMode = 'dark' | 'light' | 'sepia' | (string & {});

const STORAGE_KEY = 'kbe-theme';

/** The always-present built-in themes, in canonical cycle order. */
export const BUILTIN_MODES: ThemeMode[] = ['dark', 'light', 'sepia'];

/**
 * Derive the ordered, selectable mode list from a runtime theme map: the
 * built-ins first (dark, light, sepia — only those actually present), then any
 * config-defined theme keys in config (insertion) order. This is the dynamic
 * equivalent of the old static `MODES` array and drives both the cycle order
 * and stored-key validation.
 */
export function modesForMap(themeMap: Record<string, FluentTheme>): ThemeMode[] {
  const keys = Object.keys(themeMap);
  const builtins = BUILTIN_MODES.filter(m => keys.includes(m as string));
  const extras = keys.filter(k => !(BUILTIN_MODES as string[]).includes(k));
  return [...builtins, ...extras];
}

